<div class="panel"><form class="inline-form" method="get" action="<?= site_url('shop') ?>" data-sn-catalog-search><input name="q" placeholder="ค้นหาสินค้า…" value="<?= esc($q,'attr') ?>"><select name="category"><option value="">ทุกหมวดหมู่</option><?php foreach($categories as $c): ?><option value="<?= esc($c['category'],'attr') ?>" <?= $category===$c['category']?'selected':'' ?>><?= esc(p_category($c['category'])) ?></option><?php endforeach ?></select><button>ค้นหา</button><span class="muted" id="sn-catalog-count" role="status" aria-live="polite"><?= $total ?> รายการ</span></form></div>
<div id="sn-catalog-results" aria-live="polite" aria-busy="false"><section class="sn-products" aria-label="รายการสินค้า"><div class="sn-product-grid"><?php foreach ($products as $p): ?><?= view('platform/product_card', ['product' => $p, 'favorites' => $favorites ?? false]) ?><?php endforeach ?></div></section>
<?php if(!$products): ?><div class="panel empty">ไม่พบสินค้า</div><?php endif ?><div class="actions"><?php if($page>1): ?><a class="button secondary" href="?<?= esc(http_build_query(['q'=>$q,'category'=>$category,'page'=>$page-1]),'attr') ?>" data-sn-catalog-page>← ก่อนหน้า</a><?php endif ?><?php if($total>$page*24 && empty($favorites)): ?><a class="button secondary" href="?<?= esc(http_build_query(['q'=>$q,'category'=>$category,'page'=>$page+1]),'attr') ?>" data-sn-catalog-page>ถัดไป →</a><?php endif ?></div></div>
